previewCss:
.darma-loader-darma-b10-tetris-drop { --accent: var(--loader-color, #06b6d4); --accent-2: var(--loader-secondary-color, #f59e0b); width: var(--loader-size, 76px); height: var(--loader-size, 76px); position: relative; }
.darma-loader-darma-b10-tetris-drop span { position: absolute; width: 44%; height: 44%; border-radius: 12%; border: calc(var(--loader-size, 76px) * .012) solid color-mix(in srgb, #fff 30%, transparent); opacity: 0; animation: darma-loader-darma-b10-tetris-drop-drop calc(var(--loader-speed, 1s) * 2) ease-in infinite; }
.darma-loader-darma-b10-tetris-drop span:nth-child(1) { left: 4%; top: 4%; background: var(--accent); animation-delay: 0s; }
.darma-loader-darma-b10-tetris-drop span:nth-child(2) { right: 4%; top: 4%; background: var(--accent-2); animation-delay: calc(var(--loader-speed, 1s) * .3); }
.darma-loader-darma-b10-tetris-drop span:nth-child(3) { left: 4%; bottom: 4%; background: var(--accent-2); animation-delay: calc(var(--loader-speed, 1s) * .6); }
.darma-loader-darma-b10-tetris-drop span:nth-child(4) { right: 4%; bottom: 4%; background: var(--accent); animation-delay: calc(var(--loader-speed, 1s) * .9); }
@keyframes darma-loader-darma-b10-tetris-drop-drop { 0% { transform: translateY(-130%); opacity: 0; } 12% { opacity: 1; } 32%, 88% { transform: translateY(0); opacity: 1; } 100% { transform: translateY(0); opacity: 0; } }

